17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.util.Collection;
20	import java.util.List;
21	
22	import org.springframework.http.HttpHeaders;
23	import org.springframework.http.HttpStatus;
24	import org.springframework.http.ResponseEntity;
25	import org.springframework.samples.petclinic.mapper.OwnerMapper;
26	import org.springframework.samples.petclinic.mapper.PetMapper;
27	import org.springframework.samples.petclinic.mapper.VisitMapper;
28	import org.springframework.samples.petclinic.model.Owner;
29	import org.springframework.samples.petclinic.model.Pet;
30	import org.springframework.samples.petclinic.model.Visit;
31	import org.springframework.samples.petclinic.rest.api.OwnersApi;
32	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
33	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
34	import org.springframework.samples.petclinic.rest.dto.PetDto;
35	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
36	import org.springframework.samples.petclinic.rest.dto.VisitDto;
37	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
38	import org.springframework.samples.petclinic.service.ClinicService;
39	import org.springframework.security.access.prepost.PreAuthorize;
40	import org.springframework.web.bind.annotation.CrossOrigin;
41	import org.springframework.web.bind.annotation.RequestMapping;
42	import org.springframework.web.bind.annotation.RestController;
43	import org.springframework.web.util.UriComponentsBuilder;
44	
45	import jakarta.transaction.Transactional;
46	
47	/**
48	 * @author Vitaliy Fedoriv
49	 */
50	
51	@RestController
52	@CrossOrigin(exposedHeaders = "errors, content-type")
53	@RequestMapping("/api")
54	public class OwnerRestControllerV1 implements OwnersApi {
55	
56	    private final ClinicService clinicService;
57	
58	    private final OwnerMapper ownerMapper;
59	
60	    private final PetMapper petMapper;
61	
62	    private final VisitMapper visitMapper;
63	
64	    public OwnerRestControllerV1(ClinicService clinicService,
65	                                 OwnerMapper ownerMapper,
66	                                 PetMapper petMapper,
67	                                 VisitMapper visitMapper) {
68	        this.clinicService = clinicService;
69	        this.ownerMapper = ownerMapper;
70	        this.petMapper = petMapper;
71	        this.visitMapper = visitMapper;
72	    }
73	
74	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
75	    @Override
76	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
77	        Collection<Owner> owners;
78	        if (lastName != null) {
79	            owners = this.clinicService.findOwnerByLastName(lastName);
80	        } else {
81	            owners = this.clinicService.findAllOwners();
82	        }
83	        if (owners.isEmpty()) {
84	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
85	        }
86	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
87	    }
88	
89	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
90	    @Override
91	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
92	        Owner owner = this.clinicService.findOwnerById(ownerId);
93	        if (owner == null) {
94	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
95	        }
96	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
97	    }
98	
99	    /** Matches a syntactically valid email address: a local part and domain (with at least one dot)
100	     *  separated by '@', none of which contain whitespace or a second '@'. */
101	    private static final java.util.regex.Pattern EMAIL_PATTERN =
102	        java.util.regex.Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
103	
104	    /**
105	     * Normalize the optional email: absent stays absent; when present it must be syntactically
106	     * valid and is lower-cased. Returns {@code false} if present but invalid.
107	     */
108	    private boolean normalizeEmail(Owner owner) {
109	        String email = owner.getEmail();
110	        if (email == null || email.isEmpty()) {
111	            owner.setEmail(null);
112	            return true;
113	        }
114	        if (!EMAIL_PATTERN.matcher(email).matches()) {
115	            return false;
116	        }
117	        owner.setEmail(email.toLowerCase(java.util.Locale.ROOT));
118	        return true;
119	    }
120	
121	    /**
122	     * Normalize a telephone number to E.164 form: strip spaces, dashes and brackets; keep a leading
123	     * '+' and country code when present, otherwise assume country code '+61' and drop a single leading
124	     * '0' from the national digits. The result must have 8 to 15 digits after the '+'.
125	     *
126	     * @return the E.164 string (e.g. {@code +61412345678}), or {@code null} when the input cannot form
127	     *         a valid E.164 number.
128	     */
129	    private static String toE164(String raw) {
130	        if (raw == null) {
131	            return null;
132	        }
133	        String cleaned = raw.replaceAll("[\\s\\-()]", "");
134	        String digits;
135	        if (cleaned.startsWith("+")) {
136	            digits = cleaned.substring(1);
137	        } else {
138	            if (cleaned.startsWith("0")) {
139	                cleaned = cleaned.substring(1);
140	            }
141	            digits = "61" + cleaned;
142	        }
143	        if (!digits.matches("\\d{8,15}")) {
144	            return null;
145	        }
146	        return "+" + digits;
147	    }
148	
149	    /**
150	     * Build the customer code {@code <LAST3>-<NNNN>}: LAST3 is the upper-cased first three letters of
151	     * the last name and NNNN is a global 4-digit zero-padded sequence equal to one more than the
152	     * current number of owners (e.g. {@code SMI-0007}).
153	     */
154	    private String nextCustomerCode(String lastName) {
155	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(java.util.Locale.ROOT);
156	        int sequence = this.clinicService.findAllOwners().size() + 1;
157	        return String.format("%s-%04d", last3, sequence);
158	    }
159	
160	    /**
161	     * Normalize a value for household-duplicate comparison: {@code null} becomes empty, surrounding
162	     * whitespace is trimmed, internal runs of whitespace are collapsed to a single space and the result
163	     * is lower-cased, so the comparison is case-insensitive with collapsed whitespace.
164	     */
165	    private static String normalizeForHousehold(String value) {
166	        if (value == null) {
167	            return "";
168	        }
169	        return value.trim().replaceAll("\\s+", " ").toLowerCase(java.util.Locale.ROOT);
170	    }
171	
172	    /**
173	     * Return the owners that already share this owner's household, i.e. have the same last name and
174	     * address compared case-insensitively with collapsed whitespace.
175	     */
176	    private List<Owner> householdMembers(Owner owner) {
177	        String lastName = normalizeForHousehold(owner.getLastName());
178	        String address = normalizeForHousehold(owner.getAddress());
179	        List<Owner> members = new java.util.ArrayList<>();
180	        for (Owner existing : this.clinicService.findAllOwners()) {
181	            if (normalizeForHousehold(existing.getLastName()).equals(lastName)
182	                && normalizeForHousehold(existing.getAddress()).equals(address)) {
183	                members.add(existing);
184	            }
185	        }
186	        return members;
187	    }
188	
189	    /**
190	     * Return {@code true} when another owner already shares this owner's household, i.e. has the same
191	     * last name and address compared case-insensitively with collapsed whitespace.
192	     */
193	    private boolean sharesHouseholdWithExisting(Owner owner) {
194	        return !householdMembers(owner).isEmpty();
195	    }
196	
197	    /**
198	     * A stable, shared household identifier derived from the normalized last name and address, so every
199	     * owner in the same household deterministically resolves to the same value.
200	     */
201	    private static String householdIdFor(Owner owner) {
202	        String key = normalizeForHousehold(owner.getLastName()) + "|" + normalizeForHousehold(owner.getAddress());
203	        try {
204	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
205	                .digest(key.getBytes(java.nio.charset.StandardCharsets.UTF_8));
206	            StringBuilder sb = new StringBuilder(24);
207	            for (int i = 0; i < 12; i++) {
208	                sb.append(String.format("%02X", digest[i]));
209	            }
210	            return sb.toString();
211	        }
212	        catch (java.security.NoSuchAlgorithmException e) {
213	            throw new IllegalStateException(e);
214	        }
215	    }
216	
217	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
218	    @Override
219	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
220	        HttpHeaders headers = new HttpHeaders();
221	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
222	        String telephone = toE164(owner.getTelephone());
223	        if (telephone == null) {
224	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
225	        }
226	        if (!normalizeEmail(owner)) {
227	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
228	        }
229	        for (Owner existing : this.clinicService.findAllOwners()) {
230	            String existingTelephone = toE164(existing.getTelephone());
231	            if (telephone.equals(existingTelephone)) {
232	                return new ResponseEntity<>(HttpStatus.CONFLICT);
233	            }
234	        }
235	        List<Owner> householdMembers = householdMembers(owner);
236	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
237	        if (!sharesHousehold && !householdMembers.isEmpty()) {
238	            return new ResponseEntity<>(HttpStatus.CONFLICT);
239	        }
240	        if (sharesHousehold && !householdMembers.isEmpty()) {
241	            String householdId = householdMembers.stream()
242	                .map(Owner::getHouseholdId)
243	                .filter(id -> id != null && !id.isBlank())
244	                .findFirst()
245	                .orElseGet(() -> householdIdFor(owner));
246	            owner.setHouseholdId(householdId);
247	            for (Owner member : householdMembers) {
248	                if (member.getHouseholdId() == null || member.getHouseholdId().isBlank()) {
249	                    member.setHouseholdId(householdId);
250	                    this.clinicService.saveOwner(member);
251	                }
252	            }
253	        }
254	        owner.setTelephone(telephone);
255	        if (owner.getRegistrationDate() == null) {
256	            owner.setRegistrationDate(java.time.LocalDate.now());
257	        }
258	        owner.setCustomerCode(nextCustomerCode(owner.getLastName()));
259	        this.clinicService.saveOwner(owner);
260	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
261	        headers.setLocation(UriComponentsBuilder.newInstance()
262	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
263	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
264	    }
265	
266	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
267	    @Override
268	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
269	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
270	        if (currentOwner == null) {
271	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
272	        }
273	        currentOwner.setAddress(ownerFieldsDto.getAddress());
274	        currentOwner.setCity(ownerFieldsDto.getCity());
275	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
276	        currentOwner.setLastName(ownerFieldsDto.getLastName());
277	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
278	        currentOwner.setEmail(ownerFieldsDto.getEmail());
279	        if (!normalizeEmail(currentOwner)) {
280	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
281	        }
282	        this.clinicService.saveOwner(currentOwner);
283	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
284	    }
285	
286	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
287	    @Transactional
288	    @Override
